  background:#171e2a !important;
  border-color:var(--fleet-line) !important;
  color:var(--fleet-text) !important;
  box-shadow:none !important;
}
html body[data-floodmapper-unified] #nwDefaultNavControl#nwDefaultNavControl .nw-direction-wheel {
  border-width:1px !important;
}

